/**
 * Builds standard Customer records array from real register images
 */
export function buildBagidoraCustomers(): Customer[] {
  return BAGIDORA_RAW_DATA.map((entry) => {
    const isPaused = entry.monthlyBill === 0;
    return {
      id: `cust-bagidora-${entry.billNo}`,
      customerCode: String(entry.billNo),
      name: entry.name,
      phone: '',
      route: entry.routeHint || 'बागीदौरा मेन मार्केट',
      address: entry.name.includes('कार्यालय') || entry.name.includes('विद्यालय') ? 'बागीदौरा' : '',
      deliveryCharge: entry.deliveryCharge,
      oldDue: entry.oldDue,
      status: isPaused ? 'paused' : 'active',
      pauseDaysCount: isPaused ? 30 : 0,
      createdAt: '2026-04-01',
      notes: entry.monthlyBill !== 155 && entry.monthlyBill !== 0 ? `मासिक बिल दर: ₹${entry.monthlyBill}` : '',
    };
  });
}

/**
 * Builds payment records for customers who paid in ReC column
 */
export function buildBagidoraPayments(customers: Customer[], activeMonth: string = '2026-04'): PaymentRecord[] {
  const payments: PaymentRecord[] = [];

  BAGIDORA_RAW_DATA.forEach((entry, idx) => {
    if (entry.rec > 0) {
      const cust = customers.find((c) => c.customerCode === String(entry.billNo));
      if (cust) {
        payments.push({
          id: `pay-${entry.billNo}-${activeMonth}-${idx}`,
          customerId: cust.id,
          customerName: cust.name,
          month: activeMonth,
          amount: entry.rec,
          date: '2026-04-15',
          mode: 'cash',
          collectedBy: 'N.K. SHAH रवि मेडिकल',
          referenceNo: `REC-${entry.billNo}`,
        });
      }
    }
  });

  return payments;
}
